/**
 * Read committed events out of a harness session record, for replay in tests.
 *
 * The record is append-only concatenated zstd frames, one frame per append.
 * A frame that is not complete in the buffer is dropped rather than
 * mis-decoded: Node's `zstdDecompressSync` returns empty output without an
 * error for a frame cut in half, so completeness is decided by walking the
 * frame header and block headers.
 */
import { readFileSync } from 'node:fs';
import zlib from 'node:zlib';

/** End offset of the zstd frame at `start`, or -1 when it is incomplete. */
function frameEnd(buf, start) {
    if (start + 5 > buf.length) return -1;
    const descriptor = buf[start + 4];
    const sizeFlag = descriptor >> 6;
    const singleSegment = (descriptor >> 5) & 1;
    const checksum = ((descriptor >> 2) & 1) === 1;
    let cursor = start + 5;
    if (!singleSegment) cursor += 1;
    cursor += [0, 1, 2, 4][descriptor & 3];
    if (sizeFlag === 0) {
        if (singleSegment) cursor += 1;
    } else if (sizeFlag === 1) cursor += 2;
    else if (sizeFlag === 2) cursor += 4;
    else cursor += 8;
    for (;;) {
        if (cursor + 3 > buf.length) return -1;
        const header = buf[cursor] | (buf[cursor + 1] << 8) | (buf[cursor + 2] << 16);
        const last = header & 1;
        const type = (header >> 1) & 3;
        const size = header >> 3;
        cursor += 3;
        if (type === 3) return -1;
        cursor += type === 1 ? 1 : size;
        if (cursor > buf.length) return -1;
        if (last) return cursor + (checksum ? 4 : 0);
    }
}

/** Every committed event in one session record, in order. */
export function readSession(path) {
    const buf = readFileSync(path);
    const events = [];
    let offset = 0;
    while (offset + 4 <= buf.length) {
        if (!(buf[offset] === 0x28 && buf[offset + 1] === 0xb5 && buf[offset + 2] === 0x2f && buf[offset + 3] === 0xfd)) {
            offset += 1;
            continue;
        }
        const end = frameEnd(buf, offset);
        if (end < 0) break;
        try {
            for (const line of zlib.zstdDecompressSync(buf.subarray(offset, end)).toString('utf8').split('\n')) {
                if (line.trim()) events.push(JSON.parse(line));
            }
        } catch {
            /* skip an unreadable frame, keep reading */
        }
        offset = end;
    }
    return events;
}

/**
 * The newest `count` tool calls plus the context that came before them, as a
 * `session/event`-shaped replay.
 */
export function replayTail(path, count) {
    const events = readSession(path);
    const calls = events.filter((event) => event.type === 'tool/call');
    const tail = calls.slice(-count);
    if (tail.length === 0) return { session: events[0] ?? null, events: [] };
    const firstSeq = tail[0].seq;
    const context = events.filter((event) => event.seq <= firstSeq
        && ['user/message', 'assistant/message', 'turn/start'].includes(event.type));
    return {
        session: events[0] ?? null,
        events: [...context.slice(-3), ...tail],
    };
}

/**
 * The newest `ops` tool calls and *every* event between them and the end of the
 * record — the realistic slice a live turn produces (step starts, tool results,
 * assistant messages), for replaying without inventing events.
 */
export function replayWindow(path, ops, limit = 60) {
    const events = readSession(path);
    const calls = events.filter((event) => event.type === 'tool/call');
    if (calls.length === 0) return { session: events[0] ?? null, events: [] };
    const from = calls[Math.max(0, calls.length - ops)].seq;
    const window = events.filter((event) => event.seq >= from);
    return {
        session: events[0] ?? null,
        events: window.slice(-limit),
    };
}
